#include <bits/stdc++.h>
using namespace std;

vector<pair<int, int>> candidates;

struct StringInfo {
    int s_i;
    char first_char;
    char last_char;
};

vector<StringInfo> process_string(string s) {
    int state = 0;
    int count = 0;
    string first = s.substr(0,1);
    string last = s.substr(s.size()-1,1);
    for (char c : s) {
        if (state == 0 && c == 'n') {
            state = 1;
        } else if (state == 1 && c == 'a') {
            state = 2;
        } else if (state == 2 && c == 'r') {
            state = 3;
        } else if (state == 3 && c == 'e') {
            state = 4;
        } else if (state == 4 && c == 'k') {
            count++;
            state = 0;
        }
    }
    StringInfo info;
    info.s_i = count;
    info.first_char = first[0];
    info.last_char = last[0];
    return vector<pair<int, int>>{make_pair(info.s_i, info.last_char)};
}

int main() {
